  VALUES 
    (666::BIGINT, 'de las mejores profes que pude conocer, la materia que da es muy interesante, es muy linda persona, de los tres profes de intro y taller la mejor, amable y se nota que ama lo que hace, comprensiva, muy feliz de haberla llevado con ella, me motivó mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'de9982855cdb2973b9dc049a8542a56e69bdccf57225858d75f01abd2b892483'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'Es la mejor profe de los 3 para Intro y Taller. Sus clases son súper claras y le importan demasiado los estudiantes. Es un amor de profe, pero también se aprende mucho con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-05-15T00:00:00+00:00'::TIMESTAMPTZ, '0465ccab7c64c1e0921f4ee6a9282999d06c2a31d858c1ef7676bf8ce8f62676'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'Muy buena profe, explica muy bien y se preocupa por que los estudiantes aprendan. Es muy flexible y comprensiva. Para intro y taller es la mejor de los tres profes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '848731ec6ac70aff1569b65609fc30c1d3353be3f3bad7ff4eb5ffe1d1dde2fe'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'La profe es muy buena y ayuda mucho cuando se tienen dudas. Es bastante flexible y comprensiva. Siempre llega tarde, pero en sí es muy buena profe'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '23fba70a61117b3caae61702c9fa2ba5e8d5b3a40841abd8a73a62fbe259ede9'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'Es buena profe, no deja tareas muy largas, suele llegar entre 5 y 15 minutos tarde. Las explicaciones se hacen muy largas en algunos casos'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '574d3a37e0873aa126b909023cef12c9e0cf9c83c752648714c427f36062231a'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'Te va a ayudar siempre que lo necesités. Usualmente no atiende en las horas de consulta ya que siempre está en reuniones, por lo mismo las clases siempre suelen iniciar 10 o 15 minutos tarde.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e15fc846bf44c212d335ad4c62bfc4446aab2a62a91857bb3e089ea00131d162'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'Profesora dificil por la forma de calificar qué tiene'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-05-30T00:00:00+00:00'::TIMESTAMPTZ, '70f192ce0c3afa7dc699ee7fe494cc53fcbe84f84fff91ae7e486ba5340300a7'::TEXT, ARRAY[2510]::BIGINT[]),
    (666::BIGINT, 'Las clases largas, pero se pasa con ella fácil y se aprende, es una profe que siempre veo que dará el curso matriculo con ella de fijo xd'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-03T00:00:00+00:00'::TIMESTAMPTZ, 'f2c07b11759142518670e5f8e303ffc7bcd59ee95d72c431c3bf27d210d01975'::TEXT, ARRAY[2544]::BIGINT[]),
    (666::BIGINT, 'Este curso es una pérdida de tiempo. No tiene sentido. Pero bueno, la profe hizo el curso fácil y no demandó tiempo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '210d4942b267e17f792a79d2d9348393cb4746519a916b839bb0de68d48af2bd'::TEXT, ARRAY[2545]::BIGINT[]),
    (666::BIGINT, 'La profe es muy buena nota y gana más en modalidad presencial, es muy empática con los estudiantes. Lo que más se puede complicar del curso es la primera parte del curso (primer examen y proyecto). Por lo demás, todo bien, siempre evalúa con rúbrica y siempre da retroalimentación de los trabajos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, '27f9cdd99c80eb12d66d8f3a7d6efe0bb2bcfb95d8ea50a7b1b0a6f0b4fbc5d5'::TEXT, ARRAY[2544]::BIGINT[]),
    (666::BIGINT, 'La profe es muy buena, comprensible y comprometida, pero siento que el curso no sirve para nada, el proyecto es una pérdida de tiempo enorme. Deberían quitar estos cursos que no aportan nada y reforzar otras cosas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'ce395f621d9c58976a629f86d50b9574ce660f2f6e45716713a81e06622f0fba'::TEXT, ARRAY[2545]::BIGINT[]),
    (666::BIGINT, 'Las clases de Compu y Sociedad son livianas, el curso es lindo, el ambiente es diferente, pero que proyecto más pérdida de tiempo por Dios.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-12-14T00:00:00+00:00'::TIMESTAMPTZ, '90d412acbba1919cd37e447269495613405895ce4bf2fbf851e9be8bee868830'::TEXT, ARRAY[2545]::BIGINT[]),
    (666::BIGINT, 'El curso se va complicando durante el transcurso del semestre. Hay laboratorios o tareas todas las semanas. La profe es buena nota, comprensible. La parte negativa es que cuesta demasiado contactarla fuera de clase, porque dura hasta 4 días en contestar correos o del todo no responde.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, '0900ad32e6a7cf572da4154cb57645b72f29983c52ba4387b22dbaf12e015157'::TEXT, ARRAY[2527]::BIGINT[]),
    (666::BIGINT, 'Si pueden llevar cursos con ella, no lo duden. Excelente profe. Muy comprensiva y dispuesta a responder las consultas, tiene mucha paciencia para explicar. Se aprende montones. Tiene mucha vocación como profesora de progra. 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'e7db4478dd75e117e65198ffe23f4e56f1dde1f444107606cdba14ea2ce8d59e'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Ella es súper comprensiva, si se pide más tiempo lo va a dar sin problemas, ayuda en cuanto evaluaciones, se preocupa por los estudiantes, es buena en sí, el defecto es su voz que da un poco de sueño, pero por lo de más es 100 fijo. XD'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, '9f2a6b544b302e48763b7e3f092142bd098f0b477c6d250748283a0e2b07c4df'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'LO BUENO: ayuda mucho, deja puntos extras, te da ampliaciones de entregas de cualquier trabajo, es muy comprensiva. Explica claramente. LO MALO: diapositivas muy largas, aburre porque tiene un tono de voz bajo y muy pausado. Te podes distraer fácilmente. CONSEJO: tómese un cafecito y vaya al día.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'c04b1cf517c6bd2609ff73d5325e338c23ee3ff734bb1cbcd706f90226200f37'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Vea Bro, con ella es raro, yo no sé es raro, la mae te ayuda y todo con lo que pueda, pero nadie pasa porque es raro, osea la gente se sale porque con las clases de ella que son tan aburridas desmotiva.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'bfd76b193a67cc2aac748414043e1c148fc5b757465c1953ce02a062fd7b9625'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Las clases son suuumamente aburridas (4 horas de diapositivas). La profe es una teja, bastante accesible y comprensiva'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '04e3533c4a69b0ad7d541418e988751d6ab82b0ed53e2e249a45eaa6568f4d4c'::TEXT, ARRAY[2523]::BIGINT[]),
    (666::BIGINT, 'La profesora es muy accesible en cuanto a las fechas de entrega y ayuda mucho al estudiante. Las clases son largas y aburridas (nada prácticas, sólo diapositivas). Los exámenes son largos y los proyectos son grupales (3 personas), largos y complejos.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'd048f28a9793724e374d9ea9ae57e7aaee41f73a686dadba30033b080cca10a0'::TEXT, ARRAY[2523]::BIGINT[]),
    (666::BIGINT, 'La profe es excelente, sus clases son un poco aburridas, pero uno aprende mucho! Es super accesible y dedicada. Graba todas las clases y brinda mucha retroalimentación'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '473c4e2d1c11926591bed384f89f2d279d3e6f9c7eb524a0d2fb1468fe62b984'::TEXT, ARRAY[2527]::BIGINT[]),
    (666::BIGINT, 'La profesora es muy accesible, las clases son un poco aburridas sin embargo se logra aprender, además sube el material y videos de la clase entonces es más fácil repasar'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '09918c48be85f7ec32cb14867d43855d469ce47727924db453720ea2528f75f7'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'La profe es una excelente persona pero las clases se hacen super aburridas en algunas ocasiones'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'b60fc70925a0590c6cd0435b2b69c6d7a712517a7fd0fd3a3fefb2dd1fa840b0'::TEXT, ARRAY[2527]::BIGINT[]),
    (666::BIGINT, 'Las clases se hacen largas a veces, pero se aprende bastante, principalmente en los proyectos programados. La profesora es buena gente y ayuda mucho.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'f5997a282a6451b2365b9d47042807b5c0daafce9f502ef73c623dc0fe5ca395'::TEXT, ARRAY[1044]::BIGINT[]),
    (666::BIGINT, 'Excelente Profesora, acostumbra llegar un poco tarde, pero es bastante clara a la hora de enseñar'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '2dd46009b903ef8b5d816dc85da21aa23986df8321a8218af235e563ced8f01d'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'Explica muy bien, es una excelente profe, me gustaría llevar más cursos con ella'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '06503514a8e1626e48ed2ba8a574018169b640724a2b7b3077c1e24c76a34d9a'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'La profe es una crack en Estructuras de datos, se aprende mucho en este curso y además ella es muy buena gente. Si pueden llevar más cursos con ella háganlo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-09T00:00:00+00:00'::TIMESTAMPTZ, '1e96d8770c3c3280ee8cf908701c5fb202a29fd87fc5328bf3e0ea09c38c22f4'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Sus cursos son muy sencillos para computadores pero para el nivel de ATI están bien. Llega tarde.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, '00d1531567c33d59c5dc1d2417460779ee2b42cfb5e579ca9bf23a0f7b22f27e'::TEXT, ARRAY[33]::BIGINT[]),
    (666::BIGINT, 'Es una excelente profesora. Las clases a veces son un poco aburridas, pero en consulta atiende todas las dudas que se tenga. Los proyectos programados no complicados, pero son largos y hay que estudiar bastante para los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '2edeb25c7bb8e3b3407d505747e206f3408f6bde494e7c34203f0df2b99ed4b5'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'En este curso se aprende un montón, la profesora es muy buena gente, la recomiendo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '4989b42e28c7265dc368dcfe1d2e6ff5937057658c06c00eebb6ee7e64083107'::TEXT, ARRAY[33]::BIGINT[]),
    (666::BIGINT, 'Es muy buena profesora, las clases son un poco aburridas pero recomendada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, '4a9d0b2f6b895bc716fbb4234f11073c6bcc520f237cc03d86a0a8ba093275ab'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'La profe sabe mucho de esta materia, es super buena gente, 100% recomendada'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'a71f4b2a895827c18c85e6c739489f484ad4693246f48c5b0546684a9c94f1a2'::TEXT, ARRAY[2523]::BIGINT[]),
    (666::BIGINT, 'Excelente profesora, en este curso se nota que sabe mucho. A veces las clases se hacen un poco aburridas pero ella es un sol de persona y ayuda mucho'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'efcbb60b1dce721c78c1254de297187086ca67d9866751080dfffa91eec8342a'::TEXT, ARRAY[2523]::BIGINT[]),
    (666::BIGINT, 'Excelente profesora y persona. Califica normal, sus clases son un poco aburridas. Recomendada!!!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '910c51fb5305c14e5191d324fe378c403edec40080889c07a4d6c2ef68caab0b'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'c7ff9640f204f02f58eac26b75c14b59e8e3b3578e4c75d80b7de263dd22c81a'::TEXT, ARRAY[1249]::BIGINT[]),
    (666::BIGINT, 'Es muy buena profesora, explica cada paso a paso en las clases. Hay que poner mucha atención para entender y hacer bastantes prácticas de exámenes que manda la profe ya que se pueden parecer en el quiz o en los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-15T00:00:00+00:00'::TIMESTAMPTZ, '30678dbdc89f7a57eb233cb2a597fdc5d699c9d4a5631748876dd32d7688d457'::TEXT, ARRAY[2510]::BIGINT[]),
    (666::BIGINT, 'El curso es difícil, pero se aprende mucho. La profe es muy buena gente'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '728da4b8e6ecf193eb1a9254a080d92797b5315c053fe4e1bee5201d9b0ac870'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Se aprende mucho, los proyectos y los exámenes son un difíciles'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2017-07-18T00:00:00+00:00'::TIMESTAMPTZ, '62c4277b3f81e59a043c09ad1e7725fb96f08cd55e23b9a4d9fa753ba6f406c0'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'Se preocupa porque los estudiantes comprendan la materia, es muy buena gente'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '6fffd1a9ddf8123a264ceb965b636f790781df74040cfef7cea7ad9dcc627061'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Muy fácil con ella, aunque son clases un poco aburridas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'db18fd2cd48a4688011a5c8e3d3c30812b756bf05932314ff55495a9d2875b5c'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Es muy buena profesora, sabe mucho y es muy comprensiva'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-12T00:00:00+00:00'::TIMESTAMPTZ, '3c32576f4787b86166e7cd005228a8fdd7750c121246fec73d70b6ff9cdd58f2'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Buena profe, sabe mucho, tiene corazón para calificar las progras, aunque lea diapositivas si ud pone atención aprende mucho; Como persona es pura vida, siempre atiende dudas, recomendadisima.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '0e9b30cdd7b277d7114bfc48e1dcb3b7e144cdba43c791cba3435dddb21fbb74'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Sus clases son demasiado aburridas, da igual si se va a clase o no porque solo lee diapositivas que luego pasa. Las tareas son a veces confusas. Se pasa fácil pero se aprende poco.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'b963d40c13345cf8e52048c0ced03f5ca9fa8b0c105bd85777eff807e4871b30'::TEXT, ARRAY[2535]::BIGINT[]),
    (666::BIGINT, 'Es muy clara en sus clases, aprendí mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-07-31T00:00:00+00:00'::TIMESTAMPTZ, 'caf50dcb1b63b99415d7a2ddf7a8c65c107b5b42861408b3df3a094e27975ad3'::TEXT, ARRAY[2510]::BIGINT[]),
    (666::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '8c51bb26f334b85cd0f0ce4bd5b20ad527c203390f03787e0e7db0774da9fd5b'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Excelente profe, las clases son aburridas pero se preocupa que todo quede claro, deja pocas tareas y hace mucho quices. Como persona es muy amable y tranquila.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'ca00f1eb243ffd202b071f4539df3a2222b8c2db9dee58289a30f2dec361edad'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'exelente persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'cb50690ed545f044b3d6183b122ecbe92c84f0182e8acb0fe7133b503626cbcb'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Es el curso mas facil de la carrera que he llevado, con solo matricular y hacer todas las entregas ya tiene asegurado el 100 en el curso.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '831ffa1bc12a362ec91d9bc19a45962cded8d7435c5d6be228d20307dae8e179'::TEXT, ARRAY[2545]::BIGINT[]),
    (666::BIGINT, 'La profe es buena persona pero es super aburrida, los exámenes son muy sencillos si se estudia y los proyectos son fáciles de realizar'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'd3e51e829d8ca539d8e258573e74518f818a58b158285fa921fa9f278abb9157'::TEXT, ARRAY[2528]::BIGINT[]),
    (666::BIGINT, 'Es un amor como persona pero no es muy buena como profesora. Si busca pasar el curso fácilmente, puede llevarlo con ella. Si busca aprender, mejor matricule con otro profesor ya que solo lee las diapositivas y explica muy poco. Es muy flexible y ayuda mucho a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-25T00:00:00+00:00'::TIMESTAMPTZ, '986149de7920d77a90e6fc4115cab58266d240e127e7ba19c4278b9d86d46d41'::TEXT, ARRAY[2535]::BIGINT[]),
    (666::BIGINT, 'Excelente profesora! Explica un poco aburrido pero se asegura que uno entienda. Los examenes son normales (facil si estudia, dificil si no estudia) y con las progras es muy comprensiva. Se enfoca en el funcionamiento de las estructuras de datos en si.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'b3d890e020d5c514fb0497c2c7f7ecf38cbc8ad4703a2eeee8f50e7c2638d3c0'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Es muy buena persona, entiende mucho al estudiante. Es fácil pasar con ella. La materia es entendible, sí lee las presentaciones pero de igual forma explica todo con bastante claridad. Califica muy suave y siempre trata de ayudar al estudiante.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-05T00:00:00+00:00'::TIMESTAMPTZ, '7d294da7e43c37ec07b4a0447e6daac1fa9f4fa5264aceb8fd98cd3f22265919'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Si quiere pasar sin muchas complicaciones matricule con ella siempre va al punto claro uno tiene que practicar un poco mas en casa para poder entender completamente la materia pero es entendible y si va a consulta entiende mucho mejor la materia.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, '86c5dcc8734bf65b60ea0f88d832f2ea62a7814126cc8ae592ad9f18ad6d176c'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Como persona es buena gente, pero como profe es muy mala, no sabe explicar, es muy aburrida, solo lee las presentaciones, es fácil pasar con ella, pero no se aprende nada'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'd6e7e98bca71794c757ae0ed8dfbd1ff4c441ca46b99b0c6d063b1863acc2555'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Muy buena profe, explica muy bien, las clases se pueden volver aburridas y monótonas pero los temas se entienden bastante bien, es solo de prestar atención y si hace todos los trabajos que manda pasa sobrado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '34ad101b5b53110b9f6c258d2c97089891d808a967faa78e70cff3570d99b0b5'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2025-04-22T00:00:00+00:00'::TIMESTAMPTZ, '1ffceaafdc756f16b001bbb99516960d82b6c356a7ba10a077ded7b3ee153d46'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'Es una excelente profesora, sumamente dispuesta a ayudar, explica muy bien, y más bien es dificil que este dando este curso, entonces si lo esta dando, aprovechen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '014715247f4e30ea0818e4581f032ac04a75a18bc33b5f758bd32375cc4d3faf'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'En general la profesora se interesa por que uno entienda la materia, explica bastante bien y aclara las dudas de forma satisfactoria en clase. Siempre llega a tarde a todo y dura mucho revisando cualquier trabajo, jamás le mande un correo para evacuar dudas porque no se lo va a responder.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, '83e8c284707b3c41eaa5c7234804a388023d2da0149eaa7c57e99c6be781448a'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'De las mejores profes que puede tener ATI, 100% recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-04-26T00:00:00+00:00'::TIMESTAMPTZ, 'b8c05d389690f00b41e8a5d114ece1acc75f3c10de53c2be19aaabc3fbe48840'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (666::BIGINT, 'excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-03T00:00:00+00:00'::TIMESTAMPTZ, '0ed8a65d869c48bedc57bf985fcbfea3a06c7f0d2e37bd1d720d8a8fb5a3e3bc'::TEXT, ARRAY[2527]::BIGINT[]),
    (666::BIGINT, 'El curso es fácil y se aprende bastante. La profe... lo mismo de siempre, es buena nota, flexible pero es una misión casi imposible que le responda un correo, lo mejor es aclarar las dudas en clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-04T00:00:00+00:00'::TIMESTAMPTZ, '5e83189f5457e47a70b959e6526fd1169253312cface3efbb1951ce396742047'::TEXT, ARRAY[2544]::BIGINT[]),
    (666::BIGINT, 'Muy buena profe, lee mucho (por no decir todo) de las presentaciones. Explica poco código en comparación a la complejidad de los proyectos, por lo que se vuelve más complicado el curso debido a ese aspecto. Las demás evaluaciones son relativamente sencillas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd80c4c7214294ecd3b5a3f03ced5fad220cdd08b18eab8aa7fc4aebf1b5df057'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Ella es un amor, lee mucho, pero es lo qué hay. Califica lo justo y brinda todo el apoyo que a ella le sea posible brindar.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '2646b59711a4970d51c53587f5857314356509748c93e49fd9edfdb181285d87'::TEXT, ARRAY[2523]::BIGINT[]),
    (666::BIGINT, 'las clases son buenas, mucha teoria, codigo no mucho por eso uno se pierde un poco en proyectos, la verdad los quices son faciles, brinda ayuda y contesta rapido las dudas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, '924f4bdeb50adeed70b54f5b1d0db43ac18b9a19aca71aa07c4ee3de1ec4ddbf'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Excelente profe'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-09-18T00:00:00+00:00'::TIMESTAMPTZ, '1ab4a488de84fc79a3f583facd98645663ce97206b3bd32e97b298b2c05c0c9c'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Es de las pocas profes empáticas que hay en el TEC, eso se le agradece demasiado. Tal vez podría mejorar su metodología, especialmente en la virtualidad, se vuelve muy monótono, largo y aburrido'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'ce3e86c91fd346067f8f35e81de31fb4aa25651e6d47e707e07d3aa7a5c32881'::TEXT, ARRAY[2523]::BIGINT[]),
    (666::BIGINT, 'No le fue muy bien en clases virtuales, es súper buena explicando pero solo lo teórico, no explica nada de código... uno tiene que aprender todo solo ... los proyectos se vuelven complicado.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, '2ce541827a220d523d409b1424a16e33598820c2ce28284f3522777d74df0813'::TEXT, ARRAY[2517]::BIGINT[]),
    (666::BIGINT, 'Es una buena profe, explica bien, lo que pasa es que es curso es demasiado teórico, pero sencillo. Los exámenes son basados en las presentaciones. Recomendada.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-08-05T00:00:00+00:00'::TIMESTAMPTZ, '37d2a54fd6e1bd9ee6cd4ece50ba0df54f7080471f648edc67e9a93199cfc383'::TEXT, ARRAY[2514]::BIGINT[]),
    (666::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'c0855ea5841d117b7fb401e87243ca7ab3228d251ddc7e14f65f556b51d29d73'::TEXT, ARRAY[2510]::BIGINT[]),
    (666::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'ba8e3b76febceb13aa6b2f5e8ae69f47cc3173b4d5ff3e3ff4ddb907f8090722'::TEXT, ARRAY[2510]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
